DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ged_app') THEN
        REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
            ON ${database.defaultSchemaName}.journal_audit FROM ged_app;
        GRANT SELECT, INSERT ON ${database.defaultSchemaName}.journal_audit TO ged_app;
        GRANT USAGE ON SEQUENCE ${database.defaultSchemaName}.journal_audit_id_seq TO ged_app;
        REVOKE UPDATE ON SEQUENCE ${database.defaultSchemaName}.journal_audit_id_seq FROM ged_app;
    END IF;
END
$$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.journal_audit_creer_partition(p_instant timestamptz)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    schema_audit constant text := '${database.defaultSchemaName}';
    debut  timestamp := date_trunc('month', p_instant AT TIME ZONE 'UTC');
    fin    timestamp := debut + interval '1 month';
    suffixe text := to_char(debut, 'YYYYMM');
    nom    text := 'journal_audit_' || suffixe;
    idx    record;
BEGIN
    IF to_regclass(format('%I.%I', schema_audit, nom)) IS NOT NULL THEN
        RETURN nom;
    END IF;
    -- Deux appels concurrents pour le même mois : le second attend le premier.
    PERFORM pg_advisory_xact_lock(hashtext('journal_audit_partition'), to_char(debut, 'YYYYMM')::int);
    IF to_regclass(format('%I.%I', schema_audit, nom)) IS NOT NULL THEN
        RETURN nom;
    END IF;
    EXECUTE format('CREATE TABLE %I.%I PARTITION OF %I.journal_audit FOR VALUES FROM (%L) TO (%L)',
                   schema_audit, nom, schema_audit,
                   (debut AT TIME ZONE 'UTC'), (fin AT TIME ZONE 'UTC'));
    FOR idx IN
        SELECT enfant.relname AS nom_enfant, parent.relname AS nom_parent
          FROM pg_inherits h
          JOIN pg_class enfant ON enfant.oid = h.inhrelid
          JOIN pg_class parent ON parent.oid = h.inhparent
          JOIN pg_index i ON i.indexrelid = enfant.oid
         WHERE i.indrelid = format('%I.%I', schema_audit, nom)::regclass
    LOOP
        EXECUTE format('ALTER INDEX %I.%I RENAME TO %I',
                       schema_audit, idx.nom_enfant, idx.nom_parent || '_' || suffixe);
    END LOOP;
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE OR TRUNCATE ON %I.%I '
                   'FOR EACH STATEMENT EXECUTE FUNCTION %I.journal_audit_refuser_modification()',
                   'trg_' || nom || '_ajout_seul', schema_audit, nom, schema_audit);
    EXECUTE format('REVOKE ALL ON %I.%I FROM PUBLIC', schema_audit, nom);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ged_app') THEN
        EXECUTE format('REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON %I.%I FROM ged_app',
                       schema_audit, nom);
        EXECUTE format('GRANT SELECT, INSERT ON %I.%I TO ged_app', schema_audit, nom);
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ged_readonly') THEN
        EXECUTE format('GRANT SELECT ON %I.%I TO ged_readonly', schema_audit, nom);
    END IF;
    RETURN nom;
END
$$

DO $$
BEGIN
    REVOKE ALL ON FUNCTION ${database.defaultSchemaName}.journal_audit_creer_partition(timestamptz) FROM PUBLIC;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ged_app') THEN
        GRANT EXECUTE ON FUNCTION ${database.defaultSchemaName}.journal_audit_creer_partition(timestamptz) TO ged_app;
    END IF;
END
$$

DO $$
DECLARE
    m int;
BEGIN
    FOR m IN -1..12 LOOP
        PERFORM ${database.defaultSchemaName}.journal_audit_creer_partition(now() + make_interval(months => m));
    END LOOP;
END
$$

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ged_app') THEN
        REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
            ON ${database.defaultSchemaName}.journal_audit_scellement FROM ged_app;
        GRANT SELECT, INSERT ON ${database.defaultSchemaName}.journal_audit_scellement TO ged_app;
    END IF;
END
$$
